#!/usr/bin/env node
/**
 * Backtest throughput bench — ADR-126 follow-up #48.
 *
 * Measures bars/second + total runtime + resulting Sharpe ratio for a
 * reference backtest scenario:
 *
 *   - 1 symbol (synthetic GBM, seeded)
 *   - 252 daily bars (one trading year)
 *   - Strategy: SMA(10) / SMA(50) crossover
 *   - Position: long-only, full-capital on cross-up, exit on cross-down
 *
 * Self-contained, no live data, no `npx neural-trader` shell-out. The point
 * is to baseline the JS-side compute throughput so we have a regression
 * gate for the Phase 4 attribution / Phase 5 explainer changes (both
 * touch the per-bar hot loop).
 *
 * Output:
 *   - bars/sec
 *   - total runtime
 *   - sharpe (annualized, 252 bars/year)
 *   - max drawdown
 *   - trade count
 *
 * Run:
 *   node plugins/ruflo-neural-trader/benchmarks/backtest-throughput.bench.mjs
 *
 * Output is markdown so the result can be captured into
 * `benchmarks/results/backtest-throughput-baseline-<timestamp>.md`.
 */

const BARS = 252;                 // one trading year (daily)
const ITERATIONS = 100;           // bench reps
const WARMUP = 10;                // V8 JIT warmup
const FAST_PERIOD = 10;           // SMA-fast window
const SLOW_PERIOD = 50;           // SMA-slow window
const SEED = 314159;
const COMMISSION_BPS = 5;         // 5 basis points round-trip

// --- Seeded RNG (mulberry32 — matches other benches) --------------------
function mulberry32(seed) {
  let state = seed >>> 0;
  return function () {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- Synthetic GBM bars --------------------------------------------------
// Stable-ish ticker dynamics with a slight upward drift so SMA-cross has
// something to trade. Bars are deterministic across runs.
function makeBars(n, seed) {
  const rng = mulberry32(seed);
  const bars = new Array(n);
  let price = 100;
  for (let i = 0; i < n; i++) {
    const u1 = Math.max(rng(), 1e-9);
    const u2 = rng();
    const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    const drift = 0.0005;
    const vol = 0.015;
    const ret = drift + vol * z;
    const close = price * Math.exp(ret);
    bars[i] = { close, return: ret };
    price = close;
  }
  return bars;
}

// --- SMA cross backtest --------------------------------------------------
function runBacktest(bars) {
  const n = bars.length;
  let fastSum = 0;
  let slowSum = 0;
  let position = 0;           // 0 = flat, 1 = long
  let entryPrice = 0;
  const equity = new Array(n).fill(1.0);
  const trades = [];
  let prevFast = 0;
  let prevSlow = 0;

  for (let i = 0; i < n; i++) {
    const close = bars[i].close;

    // Rolling sums
    fastSum += close;
    slowSum += close;
    if (i >= FAST_PERIOD) fastSum -= bars[i - FAST_PERIOD].close;
    if (i >= SLOW_PERIOD) slowSum -= bars[i - SLOW_PERIOD].close;

    if (i < SLOW_PERIOD) {
      equity[i] = i > 0 ? equity[i - 1] : 1.0;
      continue;
    }

    const fastMa = fastSum / FAST_PERIOD;
    const slowMa = slowSum / SLOW_PERIOD;

    // Mark-to-market the open position first
    if (position === 1) {
      equity[i] = equity[i - 1] * (close / bars[i - 1].close);
    } else {
      equity[i] = equity[i - 1];
    }

    // Cross detection — entries trigger at next bar's open (i+1) but for
    // bench purposes we model the fill at this bar's close (the realistic
    // skill applies a fill-delay slippage model; here we want raw throughput).
    if (i > SLOW_PERIOD) {
      const crossUp = prevFast <= prevSlow && fastMa > slowMa;
      const crossDown = prevFast >= prevSlow && fastMa < slowMa;
      if (crossUp && position === 0) {
        position = 1;
        entryPrice = close;
        // Apply commission as drag on equity
        equity[i] *= 1 - COMMISSION_BPS / 1e4;
      } else if (crossDown && position === 1) {
        position = 0;
        trades.push({ entry: entryPrice, exit: close, ret: close / entryPrice - 1 });
        entryPrice = 0;
        equity[i] *= 1 - COMMISSION_BPS / 1e4;
      }
    }

    prevFast = fastMa;
    prevSlow = slowMa;
  }

  // Force-close any open position at last bar
  if (position === 1) {
    trades.push({ entry: entryPrice, exit: bars[n - 1].close, ret: bars[n - 1].close / entryPrice - 1 });
  }

  return { equity, trades };
}

// --- Metrics on equity curve --------------------------------------------
function sharpe(equity) {
  // Daily returns from equity
  const rets = new Array(equity.length - 1);
  for (let i = 1; i < equity.length; i++) {
    rets[i - 1] = equity[i] / equity[i - 1] - 1;
  }
  let sum = 0;
  for (let i = 0; i < rets.length; i++) sum += rets[i];
  const mean = sum / rets.length;
  let sse = 0;
  for (let i = 0; i < rets.length; i++) {
    const d = rets[i] - mean;
    sse += d * d;
  }
  const std = Math.sqrt(sse / (rets.length - 1));
  if (std === 0) return 0;
  // Annualize: √252 for daily data
  return (mean / std) * Math.sqrt(252);
}

function maxDrawdown(equity) {
  let peak = equity[0];
  let maxDd = 0;
  for (let i = 0; i < equity.length; i++) {
    if (equity[i] > peak) peak = equity[i];
    const dd = (equity[i] - peak) / peak;
    if (dd < maxDd) maxDd = dd;
  }
  return maxDd;
}

// --- Bench ---------------------------------------------------------------
console.log('# Backtest throughput — bench results');
console.log('');
console.log(`Generated: ${new Date().toISOString()}`);
console.log(`Node: ${process.version}`);
console.log(`Bars: ${BARS} (1y daily)`);
console.log(`Strategy: SMA(${FAST_PERIOD}) / SMA(${SLOW_PERIOD}) crossover`);
console.log(`Commission: ${COMMISSION_BPS} bps round-trip`);
console.log(`Iterations: ${ITERATIONS} (warmup: ${WARMUP})`);
console.log(`Seed: ${SEED}`);
console.log('');

const bars = makeBars(BARS, SEED);

// Warmup
for (let i = 0; i < WARMUP; i++) runBacktest(bars);

// Timed
const ms = new Array(ITERATIONS);
let lastResult;
for (let i = 0; i < ITERATIONS; i++) {
  const t0 = performance.now();
  lastResult = runBacktest(bars);
  ms[i] = performance.now() - t0;
}

ms.sort((a, b) => a - b);
const avgMs = ms.reduce((s, x) => s + x, 0) / ms.length;
const p50Ms = ms[Math.floor(ms.length / 2)];
const p95Ms = ms[Math.floor(ms.length * 0.95)];
const p99Ms = ms[Math.floor(ms.length * 0.99)];
const barsPerSec = (BARS / (avgMs / 1000));

// Strategy metrics
const sh = sharpe(lastResult.equity);
const dd = maxDrawdown(lastResult.equity);
const finalEq = lastResult.equity[lastResult.equity.length - 1];

console.log('## Throughput');
console.log('');
console.log('| Metric            | Value         |');
console.log('|-------------------|---------------|');
console.log(`| Avg runtime       | ${avgMs.toFixed(4)} ms |`);
console.log(`| p50 runtime       | ${p50Ms.toFixed(4)} ms |`);
console.log(`| p95 runtime       | ${p95Ms.toFixed(4)} ms |`);
console.log(`| p99 runtime       | ${p99Ms.toFixed(4)} ms |`);
console.log(`| Bars/sec          | ${barsPerSec.toFixed(0)} |`);
console.log('');
console.log('## Strategy metrics (last iteration)');
console.log('');
console.log('| Metric            | Value         |');
console.log('|-------------------|---------------|');
console.log(`| Final equity      | ${finalEq.toFixed(4)} (vs 1.000 start) |`);
console.log(`| Sharpe (ann.)     | ${sh.toFixed(3)} |`);
console.log(`| Max drawdown      | ${(dd * 100).toFixed(2)}% |`);
console.log(`| Trade count       | ${lastResult.trades.length} |`);
console.log('');
console.log('## Acceptance');
console.log('');
console.log(`- Avg runtime: **${avgMs.toFixed(4)} ms** (target: <10 ms — ${avgMs < 10 ? 'PASS' : 'FAIL'})`);
console.log(`- Throughput: **${barsPerSec.toFixed(0)} bars/sec** (target: >25,000 bars/sec — ${barsPerSec > 25000 ? 'PASS' : 'FAIL'})`);
console.log('');
console.log('## Notes');
console.log('');
console.log('- The reference scenario is deliberately small (1y / 1 symbol /');
console.log('  1 strategy) so the bench measures the per-bar compute kernel,');
console.log('  not memory pressure or GC behavior. Walk-forward and');
console.log('  Monte-Carlo variants are upstream `npx neural-trader` features');
console.log('  and are NOT modeled here.');
console.log('- Commissions are applied as equity drag at fill time (5 bps');
console.log('  round-trip is the SOTA mid-cap-ETF default the skill uses).');
console.log('');
console.log('## Refs');
console.log('');
console.log('- ADR-126 §SOTA delta — bench-driven perf work');
console.log('- `plugins/ruflo-neural-trader/skills/trader-backtest/SKILL.md` — production backtest path');

#!/usr/bin/env node
/**
 * Memory recall bench — ADR-126 follow-up #48.
 *
 * Measures `mcp__claude-flow__memory_search`-style latency over the
 * `trading-backtests` namespace at three sizes: N ∈ {100, 1000, 5000}
 * entries.
 *
 * Approach:
 *   The production memory backend (AgentDB + HNSW) requires SQLite + ONNX
 *   embedder bootstrap, which is too heavy a dependency surface for a
 *   bench shipped in a Claude Code plugin (no package.json, no build).
 *   Instead we model the same algorithmic core: cosine-similarity search
 *   over a deterministic-seeded set of 384-dim embeddings, with the same
 *   top-K + threshold logic the skill uses.
 *
 *   For each size N we measure:
 *     - p50 / p95 latency for top-K search
 *     - recall@K — fraction of "ground-truth" near-neighbors recovered
 *       (using a brute-force top-K on a held-out query set as truth)
 *
 *   This bench is what would change if the skill switched between linear
 *   scan and HNSW; the latency curve is the regression gate.
 *
 * Output:
 *   - latency table at N ∈ {100, 1000, 5000}
 *   - recall@K (K=10) at each size
 *   - ops/sec at each size
 *
 * Run:
 *   node plugins/ruflo-neural-trader/benchmarks/memory-recall.bench.mjs
 *
 * Output is markdown, capturable to
 * `benchmarks/results/memory-recall-baseline-<timestamp>.md`.
 */

const SIZES = [100, 1000, 5000];
const DIM = 384;                  // matches all-MiniLM-L6-v2 ONNX output
const K = 10;                     // top-K
const QUERY_COUNT = 50;           // queries per size for averaging
const WARMUP = 5;
const SEED = 271828;

// --- Seeded RNG ----------------------------------------------------------
function mulberry32(seed) {
  let state = seed >>> 0;
  return function () {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- Embedding generator -------------------------------------------------
// Box-Muller produces ~N(0,1); we normalize to the unit sphere so the
// cosine kernel is equivalent to dot product. Each entry is independent.
function makeEmbedding(rng) {
  const v = new Float32Array(DIM);
  for (let i = 0; i < DIM; i += 2) {
    const u1 = Math.max(rng(), 1e-9);
    const u2 = rng();
    const r = Math.sqrt(-2 * Math.log(u1));
    v[i] = r * Math.cos(2 * Math.PI * u2);
    if (i + 1 < DIM) v[i + 1] = r * Math.sin(2 * Math.PI * u2);
  }
  // L2 normalize
  let norm = 0;
  for (let i = 0; i < DIM; i++) norm += v[i] * v[i];
  norm = Math.sqrt(norm) || 1;
  for (let i = 0; i < DIM; i++) v[i] /= norm;
  return v;
}

// --- Linear scan top-K search -------------------------------------------
function topK(queries, query, k) {
  // queries: array of Float32Array (the corpus)
  // query: Float32Array
  // returns: array of {idx, score} sorted by score desc
  const scores = new Array(queries.length);
  for (let i = 0; i < queries.length; i++) {
    const v = queries[i];
    let dot = 0;
    for (let d = 0; d < DIM; d++) dot += v[d] * query[d];
    scores[i] = { idx: i, score: dot };
  }
  // Partial sort — top-K by score
  scores.sort((a, b) => b.score - a.score);
  return scores.slice(0, k);
}

// --- Percentile helpers --------------------------------------------------
function percentile(sorted, p) {
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
}

// --- Bench ---------------------------------------------------------------
console.log('# Memory recall (trading-backtests namespace) — bench results');
console.log('');
console.log(`Generated: ${new Date().toISOString()}`);
console.log(`Node: ${process.version}`);
console.log(`Embedding dim: ${DIM} (matches all-MiniLM-L6-v2 / ONNX)`);
console.log(`K: ${K}`);
console.log(`Query count per size: ${QUERY_COUNT}`);
console.log(`Seed: ${SEED}`);
console.log('');
console.log('## Latency by corpus size');
console.log('');
console.log('| N    | avg (ms) | p50 (ms) | p95 (ms) | Ops/sec   | Recall@10 |');
console.log('|------|----------|----------|----------|-----------|-----------|');

const results = [];
for (const n of SIZES) {
  const rng = mulberry32(SEED + n);

  // Build the corpus (this dominates startup cost — not timed)
  const corpus = new Array(n);
  for (let i = 0; i < n; i++) corpus[i] = makeEmbedding(rng);

  // Build query set (drawn independently)
  const queryRng = mulberry32(SEED + n + 1);
  const queries = new Array(QUERY_COUNT);
  for (let i = 0; i < QUERY_COUNT; i++) queries[i] = makeEmbedding(queryRng);

  // Warmup
  for (let i = 0; i < WARMUP; i++) topK(corpus, queries[i % QUERY_COUNT], K);

  // Timed runs
  const ms = new Array(QUERY_COUNT);
  let lastTopK;
  for (let i = 0; i < QUERY_COUNT; i++) {
    const t0 = performance.now();
    lastTopK = topK(corpus, queries[i], K);
    ms[i] = performance.now() - t0;
  }
  ms.sort((a, b) => a - b);
  const avgMs = ms.reduce((s, x) => s + x, 0) / ms.length;
  const p50 = percentile(ms, 50);
  const p95 = percentile(ms, 95);
  const opsPerSec = 1000 / avgMs;

  // Recall@K — since we ARE running linear scan, by construction recall@K
  // is 1.0 against itself. To produce a non-trivial number we compute
  // recall on a SUBSET corpus (drop random 10% of corpus, re-search, see
  // how many ground-truth neighbors are recovered). This mimics the
  // approximate-vs-exact gap an HNSW backend would have.
  const subsetSize = Math.floor(n * 0.9);
  const subset = corpus.slice(0, subsetSize);
  const groundTruth = topK(corpus, queries[0], K).map((r) => r.idx).filter((i) => i < subsetSize);
  const approx = topK(subset, queries[0], K).map((r) => r.idx);
  const recovered = groundTruth.filter((g) => approx.includes(g)).length;
  const recall = groundTruth.length > 0 ? recovered / groundTruth.length : 1.0;

  results.push({ n, avgMs, p50, p95, opsPerSec, recall });

  console.log(
    `| ${String(n).padEnd(4)} | ${avgMs.toFixed(4).padEnd(8)} | ${p50.toFixed(4).padEnd(8)} | ${p95.toFixed(4).padEnd(8)} | ${opsPerSec.toFixed(0).padEnd(9)} | ${recall.toFixed(3).padEnd(9)} |`,
  );
}

// --- Scaling factor — how does latency grow with N? ---------------------
const at100 = results.find((r) => r.n === 100);
const at5000 = results.find((r) => r.n === 5000);
const scalingFactor = at5000.avgMs / at100.avgMs;
const idealLinear = 5000 / 100; // 50x — linear scan grows O(N)
const subLinearity = scalingFactor / idealLinear;

console.log('');
console.log('## Scaling');
console.log('');
console.log(`- Latency at N=100:  ${at100.avgMs.toFixed(4)} ms`);
console.log(`- Latency at N=5000: ${at5000.avgMs.toFixed(4)} ms`);
console.log(`- Scaling factor: ${scalingFactor.toFixed(2)}x (ideal linear: ${idealLinear}x)`);
console.log(`- Effective sub-linearity: ${(subLinearity * 100).toFixed(0)}% of linear`);
console.log('');
console.log('## Acceptance');
console.log('');
console.log(`- p95 at N=5000: **${at5000.p95.toFixed(4)} ms** (target: <50 ms — ${at5000.p95 < 50 ? 'PASS' : 'FAIL'})`);
console.log(`- Recall@10 at all N: **${results.every((r) => r.recall >= 0.8) ? 'PASS' : 'FAIL'}** (target: ≥0.8 against ground-truth subset)`);
console.log('');
console.log('## Notes');
console.log('');
console.log('- This bench models a **linear scan** baseline. The production');
console.log('  backend uses HNSW (ADR-006), which is 150x-12,500x faster on');
console.log('  the same data at the same dim — that gap is the optimization');
console.log('  budget the bench should track as memory grows.');
console.log('- Embeddings are unit-norm 384-dim Gaussian — a reasonable proxy');
console.log('  for the ONNX all-MiniLM-L6-v2 output distribution.');
console.log('- Recall@K is computed against a 90% subset of the corpus; in a');
console.log('  real ANN deployment this is the approximate-vs-exact gap.');
console.log('');
console.log('## Refs');
console.log('');
console.log('- ADR-126 §SOTA delta — bench-driven perf work');
console.log('- ADR-006 — Unified Memory Service (HNSW)');
console.log('- `plugins/ruflo-neural-trader/skills/trader-backtest/SKILL.md` — production recall path');

#!/usr/bin/env node
/**
 * Portfolio CG vs Neumann bench — ADR-126 Phase 3, ADR-123 Wedge 8.
 *
 * Compares three solvers on synthetic SPD covariance matrices at
 * n ∈ {16, 64, 256}. Output columns:
 *
 *   - cg_local_avg_ms              — local JS CG kernel
 *   - cg_sublinear_native_avg_ms   — native dispatch via mcp__ruflo-sublinear__solve
 *                                    (only measured when the tool surface is
 *                                    reachable in this runtime — see #55)
 *   - neumann_solve_avg_ms         — legacy Jacobi-Neumann (the path the CLI
 *                                    `npx neural-trader --portfolio optimize`
 *                                    walks at ADR-126 Phase 3 write-time)
 *   - speedup                      — neumann / cg ratio
 *   - parity                       — ||cg − neumann||_∞ on fixed seed (<1e-4)
 *
 * When the native path is NOT reachable, the native column is reported as
 * "n/a (native not available)" and the bench still ships a useful local-JS
 * baseline. The full 40-60× headline requires the daemon to be up so the
 * MCP tool is mounted into globalThis — CI exercises that path.
 *
 * Self-contained — no external runtime deps beyond Node 20+ stdlib.
 *
 * Run:
 *   node plugins/ruflo-neural-trader/benchmarks/portfolio-cg.bench.mjs
 *
 * Output is markdown so the result can be captured directly into
 * benchmarks/results/cg-native-baseline-<timestamp>.md.
 */

import { conjugateGradient, neumannSeries, SublinearAdapter, sublinearAdapter } from '../src/sublinear-adapter.mjs';

const SIZES = [16, 64, 256];
const ITERATIONS = 100;          // bench reps per size
const WARMUP = 10;               // warmup reps before timing (V8 JIT)
const TOLERANCE = 1e-6;
const SEED = 42;

// --- Seeded RNG (mulberry32 — deterministic across Node versions) -------
function mulberry32(seed) {
  let state = seed >>> 0;
  return function () {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- Synthetic SPD + barely-diagonally-dominant covariance --------------
// Realistic portfolio covariance has highly correlated assets (think
// tech-sector ETFs against each other). Such matrices have eigenvalue
// spectra that are nasty for Jacobi — the spectral radius of (I − D⁻¹A)
// approaches 1, so Neumann iteration count grows ~ log(1/tol) / (1 − ρ),
// which can run into the thousands.
//
// CG, by contrast, converges in iterations proportional to √κ(A) at
// most, and far fewer when eigenvalues cluster (which they do for
// correlated assets). This is exactly the regime ADR-123 Wedge 8 targets.
//
// Construction:
//   1. Strong off-diagonal correlations in [−0.45, 0.45] so the matrix is
//      barely SPD/DD — Jacobi will struggle.
//   2. Diagonal set to the row off-sum (i.e. ρ(Jacobi) ≈ 1) plus a tiny ε
//      → strictly DD by ε, but contraction rate close to 1.
function makeSpdCovariance(n, rng) {
  const A = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const v = (rng() - 0.5) * 0.9; // [−0.45, 0.45]
      A[i][j] = v;
      A[j][i] = v;
    }
  }
  for (let i = 0; i < n; i++) {
    let off = 0;
    for (let j = 0; j < n; j++) if (j !== i) off += Math.abs(A[i][j]);
    // Tiny ε above the DD threshold makes Jacobi contraction rate ≈ 1.
    A[i][i] = off * 1.001 + 1e-4;
  }
  return A;
}

function makeExpectedReturns(n, rng) {
  return Array.from({ length: n }, () => (rng() - 0.5) * 0.1);
}

function infNorm(a, b) {
  let m = 0;
  for (let i = 0; i < a.length; i++) {
    const d = Math.abs((a[i] || 0) - (b[i] || 0));
    if (d > m) m = d;
  }
  return m;
}

function benchOne(fn, A, b, opts) {
  const ms = [];
  for (let i = 0; i < WARMUP; i++) fn(A, b, opts);
  for (let i = 0; i < ITERATIONS; i++) {
    const t0 = performance.now();
    fn(A, b, opts);
    ms.push(performance.now() - t0);
  }
  ms.sort((x, y) => x - y);
  const sum = ms.reduce((s, x) => s + x, 0);
  return {
    avgMs: sum / ms.length,
    medianMs: ms[Math.floor(ms.length / 2)],
    minMs: ms[0],
    maxMs: ms[ms.length - 1],
  };
}

// --- Native availability probe ------------------------------------------
//
// The native dispatch is reachable iff `mcp__ruflo-sublinear__solve` is
// mounted on globalThis (or RUFLO_SUBLINEAR_NATIVE=1 forces an attempt).
// When reachable, we run the adapter end-to-end and capture its latency.
// When not, we still produce a useful local-JS baseline.
const NATIVE_AVAILABLE = SublinearAdapter.detectSublinearTool();

// --- Run -----------------------------------------------------------------
console.log('# Portfolio CG vs Neumann — bench results');
console.log('');
console.log(`Generated: ${new Date().toISOString()}`);
console.log(`Node: ${process.version}`);
console.log(`Iterations per size: ${ITERATIONS} (warmup: ${WARMUP})`);
console.log(`Tolerance: ${TOLERANCE}`);
console.log(`Seed: ${SEED}`);
console.log(`Native sublinear tool: ${NATIVE_AVAILABLE ? 'AVAILABLE' : 'NOT AVAILABLE (local JS fallback only)'}`);
console.log('');
console.log('| n    | CG local (ms) | CG native (ms)     | Neumann (ms) | Local speedup | Native speedup | CG iters | Neumann iters | Parity (∞-norm) |');
console.log('|------|---------------|--------------------|--------------|---------------|----------------|----------|---------------|-----------------|');

let allParityOk = true;
const results = [];

// Async benchOne for the adapter (whose solveCG is async).
async function benchOneAsync(adapter, A, b, opts) {
  const ms = [];
  for (let i = 0; i < WARMUP; i++) await adapter.solveCG(A, b, opts);
  for (let i = 0; i < ITERATIONS; i++) {
    const t0 = performance.now();
    await adapter.solveCG(A, b, opts);
    ms.push(performance.now() - t0);
  }
  ms.sort((x, y) => x - y);
  const sum = ms.reduce((s, x) => s + x, 0);
  return {
    avgMs: sum / ms.length,
    medianMs: ms[Math.floor(ms.length / 2)],
    minMs: ms[0],
    maxMs: ms[ms.length - 1],
  };
}

for (const n of SIZES) {
  const rng = mulberry32(SEED);
  const A = makeSpdCovariance(n, rng);
  const b = makeExpectedReturns(n, rng);

  const cgOpts = { tolerance: TOLERANCE, maxIterations: 200 };
  const nmOpts = { tolerance: TOLERANCE, maxIterations: 5000 };

  // Parity first — use a single shared run for the solutions.
  const cgResult = conjugateGradient(A, b, cgOpts);
  const nmResult = neumannSeries(A, b, nmOpts);
  const parity = infNorm(cgResult.solution, nmResult.solution);
  const parityOk = parity < 1e-4;
  if (!parityOk) allParityOk = false;

  // Timing — separate runs, JIT-warmed.
  const cgBench = benchOne(conjugateGradient, A, b, cgOpts);
  const nmBench = benchOne(neumannSeries, A, b, nmOpts);

  // Native dispatch — only when reachable. Use a fresh adapter for hygiene.
  // The adapter's solveCG path either dispatches to the native tool
  // (path: 'cg-mcp') or falls through to local JS (path: 'cg-local'). We
  // capture both the bench latency and which path was actually walked.
  let nativeBench = null;
  let nativeMethod = null;
  if (NATIVE_AVAILABLE) {
    try {
      const adapter = sublinearAdapter;
      const probe = await adapter.solveCG(A, b, cgOpts);
      nativeMethod = probe.method;
      // Only bench if we actually got the native path; if the adapter fell
      // through to local JS for any reason, skip — the cg-local column
      // already covers that case.
      if (probe.method === 'cg-sublinear-native') {
        nativeBench = await benchOneAsync(adapter, A, b, cgOpts);
      }
    } catch {
      /* native attempt threw — skip native measurement */
    }
  }

  const localSpeedup = nmBench.avgMs / cgBench.avgMs;
  const nativeSpeedup = nativeBench ? nmBench.avgMs / nativeBench.avgMs : null;

  results.push({
    n,
    cgAvgMs: cgBench.avgMs,
    cgNativeAvgMs: nativeBench ? nativeBench.avgMs : null,
    nativeMethod,
    neumannAvgMs: nmBench.avgMs,
    localSpeedup,
    nativeSpeedup,
    cgIters: cgResult.iterations,
    neumannIters: nmResult.iterations,
    parity,
    parityOk,
  });

  const nativeCell = nativeBench
    ? nativeBench.avgMs.toFixed(4)
    : 'n/a (native not avail)';
  const nativeSpeedupCell = nativeSpeedup
    ? `${nativeSpeedup.toFixed(2)}×`
    : 'n/a';
  console.log(
    `| ${String(n).padEnd(4)} | ${cgBench.avgMs.toFixed(4).padEnd(13)} | ${String(nativeCell).padEnd(18)} | ${nmBench.avgMs.toFixed(4).padEnd(12)} | ${(localSpeedup.toFixed(2) + '×').padEnd(13)} | ${nativeSpeedupCell.padEnd(14)} | ${String(cgResult.iterations).padEnd(8)} | ${String(nmResult.iterations).padEnd(13)} | ${parity.toExponential(2).padEnd(15)} |`,
  );
}

console.log('');
console.log('## Acceptance');
console.log('');
const at256 = results.find((r) => r.n === 256);
console.log(`- CG (local JS) latency at n=256: **${at256.cgAvgMs.toFixed(4)} ms** (target: <1 ms — ${at256.cgAvgMs < 1 ? 'PASS' : 'FAIL'})`);
if (at256.cgNativeAvgMs != null) {
  console.log(`- CG (native) latency at n=256: **${at256.cgNativeAvgMs.toFixed(4)} ms** (via \`mcp__ruflo-sublinear__solve\`)`);
  console.log(`- Native speedup at n=256: **${at256.nativeSpeedup.toFixed(2)}×** vs Neumann (target: 40-60× per ADR-123 Wedge 8)`);
} else {
  console.log('- CG (native) latency: **n/a** — native dispatch surface not reachable from this runtime');
  console.log('  - Reasons it can be unreachable: ruflo daemon not running, ruflo-sublinear plugin not registered, or the agent sandbox does not mount MCP tools onto globalThis. Set `RUFLO_SUBLINEAR_NATIVE=1` to force a dispatch attempt.');
}
console.log(`- Local JS speedup at n=256: **${at256.localSpeedup.toFixed(2)}×** vs Neumann (JS-vs-JS gap — both kernels converge in O(few) iterations on well-conditioned SPD inputs, so the gap is dominated by per-iter constant factors. The full 40-60× requires the native kernel.)`);
console.log(`- Parity at all n: **${allParityOk ? 'PASS' : 'FAIL'}** (||cg − neumann||_∞ < 1e-4)`);
console.log('');
console.log('## Refs');
console.log('');
console.log('- ADR-126 Phase 3 — `plugins/ruflo-neural-trader/src/sublinear-adapter.ts`');
console.log('- ADR-123 §162 Row 8 — Wedge 8 portfolio CG');
console.log('- Upstream `sublinear-time-solver@1.7.0` — production CG kernel target');
console.log('- Task #55 — native CG dispatch wiring (this bench column)');

// Exit non-zero if parity is broken — that's a correctness regression.
if (!allParityOk) {
  console.error('');
  console.error('FAIL: parity check broke at one or more sizes (||cg − neumann||_∞ ≥ 1e-4)');
  process.exit(1);
}

#!/usr/bin/env node
/**
 * Signal generation bench — ADR-126 follow-up #48.
 *
 * Measures end-to-end latency of the trader-signal scan path for a small
 * representative ticker list. To keep the bench REPRODUCIBLE we do NOT hit
 * live Yahoo (the `trader-signal` skill spawns `npx neural-trader --signal
 * scan` against live feeds in production). Instead we exercise the same
 * arithmetic core — anomaly detection via Z-score over a deterministic
 * synthetic OHLCV series — and time it directly.
 *
 * The two paths share the same shape:
 *
 *   1. Build a window of N bars per symbol.
 *   2. Compute rolling mean + stddev.
 *   3. Score the latest bar against the rolling window (Z-score).
 *   4. Classify into one of the 6 anomaly categories the skill enumerates
 *      (spike, drift, flatline, oscillation, pattern-break, cluster-outlier).
 *
 * That core is what dominates real `--signal scan` latency once the network
 * fetch is amortized (the cloud fetch is a fixed ~200 ms tail latency the
 * skill can't optimize from the JS side).
 *
 * Output: avg / p50 / p95 / p99 / ops-per-sec per symbol, plus the aggregate
 * scan latency (sum across symbols).
 *
 * Run:
 *   node plugins/ruflo-neural-trader/benchmarks/signal-generation.bench.mjs
 *
 * Output is markdown so the result can be captured into
 * `benchmarks/results/signal-generation-baseline-<timestamp>.md`.
 */

const SYMBOLS = ['AAPL', 'MSFT', 'NVDA', 'TSLA', 'SPY'];
const WINDOW_BARS = 252;          // one trading year of daily bars
const ITERATIONS = 200;           // bench reps per symbol
const WARMUP = 20;                // V8 JIT warmup
const SEED = 137;                 // deterministic across runs

// --- Seeded RNG (mulberry32 — matches portfolio-cg.bench.mjs) -----------
function mulberry32(seed) {
  let state = seed >>> 0;
  return function () {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// --- Synthetic OHLCV — GBM-ish walk with regime-shifted volatility ------
// Realistic ticker-level dynamics: drift + log-normal returns, with a
// volatility bump at the tail so the latest bar is more likely to score
// anomalously (mimicking the regime the `--signal scan` skill is built to
// catch — `drift`, `spike`, `pattern-break`).
function makeBars(symbolSeed, n) {
  const rng = mulberry32(symbolSeed);
  const bars = new Array(n);
  let price = 100 + rng() * 50; // starting price in [100, 150]
  for (let i = 0; i < n; i++) {
    // Box-Muller for ~N(0,1)
    const u1 = Math.max(rng(), 1e-9);
    const u2 = rng();
    const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    // Regime: amplify vol in last 5% of window so latest bar is anomalous.
    const vol = i > n * 0.95 ? 0.04 : 0.012;
    const drift = 0.0003;
    const ret = drift + vol * z;
    const open = price;
    const close = open * Math.exp(ret);
    const high = Math.max(open, close) * (1 + Math.abs(rng()) * 0.005);
    const low = Math.min(open, close) * (1 - Math.abs(rng()) * 0.005);
    const volume = Math.floor(1e6 + rng() * 5e6);
    bars[i] = { open, high, low, close, volume };
    price = close;
  }
  return bars;
}

// --- Anomaly core — what `--signal scan` does per symbol ----------------
function computeStats(bars) {
  const closes = bars.map((b) => b.close);
  const n = closes.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += closes[i];
  const mean = sum / n;
  let sse = 0;
  for (let i = 0; i < n; i++) {
    const d = closes[i] - mean;
    sse += d * d;
  }
  const std = Math.sqrt(sse / (n - 1));
  return { mean, std };
}

function classify(zSeries) {
  // Multi-dimensional Z signal — mimics the skill's 6-class output.
  let maxZ = 0;
  let signFlips = 0;
  let highCount = 0;
  let prev = 0;
  for (let i = 0; i < zSeries.length; i++) {
    const z = zSeries[i];
    const a = Math.abs(z);
    if (a > maxZ) maxZ = a;
    if (a > 2) highCount++;
    if (i > 0 && Math.sign(z) !== Math.sign(prev) && Math.abs(prev) > 1) signFlips++;
    prev = z;
  }
  const lastZ = zSeries[zSeries.length - 1];
  if (maxZ > 5) return 'spike';
  if (highCount > zSeries.length * 0.3 && Math.abs(lastZ) > 1.5) return 'drift';
  if (maxZ < 0.5) return 'flatline';
  if (signFlips > zSeries.length * 0.2) return 'oscillation';
  if (highCount > zSeries.length * 0.5) return 'cluster-outlier';
  if (highCount > 3 && signFlips > 1) return 'pattern-break';
  return 'normal';
}

function scanSymbol(bars) {
  // 1. rolling baseline (first 80% of bars)
  const baselineEnd = Math.floor(bars.length * 0.8);
  const baseline = bars.slice(0, baselineEnd);
  const tail = bars.slice(baselineEnd);
  const { mean, std } = computeStats(baseline);

  // 2. score every tail bar
  const zSeries = new Array(tail.length);
  for (let i = 0; i < tail.length; i++) {
    zSeries[i] = std > 0 ? (tail[i].close - mean) / std : 0;
  }

  // 3. classify
  const anomalyType = classify(zSeries);
  const maxZ = zSeries.reduce((m, z) => Math.max(m, Math.abs(z)), 0);

  return { anomalyType, maxZ, lastZ: zSeries[zSeries.length - 1] };
}

// --- Percentile helpers --------------------------------------------------
function percentile(sorted, p) {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
}

function summarize(ms) {
  const sorted = [...ms].sort((a, b) => a - b);
  const sum = sorted.reduce((s, x) => s + x, 0);
  const avg = sum / sorted.length;
  return {
    avg,
    p50: percentile(sorted, 50),
    p95: percentile(sorted, 95),
    p99: percentile(sorted, 99),
    opsPerSec: 1_000_000 / avg, // avg is in µs
  };
}

// --- Run -----------------------------------------------------------------
console.log('# trader-signal scan latency — bench results');
console.log('');
console.log(`Generated: ${new Date().toISOString()}`);
console.log(`Node: ${process.version}`);
console.log(`Symbols: ${SYMBOLS.join(', ')}`);
console.log(`Window: ${WINDOW_BARS} bars per symbol`);
console.log(`Iterations per symbol: ${ITERATIONS} (warmup: ${WARMUP})`);
console.log(`Seed: ${SEED}`);
console.log('');
console.log('## Per-symbol latency');
console.log('');
console.log('| Symbol | Avg (µs) | p50 (µs) | p95 (µs) | p99 (µs) | Ops/sec   | Anomaly        |');
console.log('|--------|----------|----------|----------|----------|-----------|----------------|');

const perSymbol = [];
for (let s = 0; s < SYMBOLS.length; s++) {
  const symbol = SYMBOLS[s];
  // Different seed per symbol so each gets its own series.
  const symSeed = SEED + s * 31;
  const bars = makeBars(symSeed, WINDOW_BARS);

  // Warmup
  for (let i = 0; i < WARMUP; i++) scanSymbol(bars);

  // Timed runs (perf.now resolves in microseconds in Node 20+)
  const us = new Array(ITERATIONS);
  let lastResult;
  for (let i = 0; i < ITERATIONS; i++) {
    const t0 = performance.now();
    lastResult = scanSymbol(bars);
    us[i] = (performance.now() - t0) * 1000; // ms -> µs
  }

  const summary = summarize(us);
  perSymbol.push({ symbol, ...summary, anomaly: lastResult.anomalyType });

  console.log(
    `| ${symbol.padEnd(6)} | ${summary.avg.toFixed(2).padEnd(8)} | ${summary.p50.toFixed(2).padEnd(8)} | ${summary.p95.toFixed(2).padEnd(8)} | ${summary.p99.toFixed(2).padEnd(8)} | ${summary.opsPerSec.toFixed(0).padEnd(9)} | ${lastResult.anomalyType.padEnd(14)} |`,
  );
}

// --- Aggregate scan latency — what a full `--signal scan` costs ---------
const aggMs = SYMBOLS.map((_, i) => perSymbol[i].avg / 1000).reduce((s, x) => s + x, 0);
const aggP95Ms = SYMBOLS.map((_, i) => perSymbol[i].p95 / 1000).reduce((s, x) => s + x, 0);

console.log('');
console.log('## Aggregate (full scan)');
console.log('');
console.log(`- Sum-of-avgs across ${SYMBOLS.length} symbols: **${aggMs.toFixed(3)} ms**`);
console.log(`- Sum-of-p95s across ${SYMBOLS.length} symbols: **${aggP95Ms.toFixed(3)} ms**`);
console.log('');
console.log('## Acceptance');
console.log('');
const maxAvg = Math.max(...perSymbol.map((r) => r.avg));
const PASS_AVG = maxAvg < 1000; // < 1 ms per symbol
console.log(`- Worst-symbol avg latency: **${maxAvg.toFixed(2)} µs** (target: <1000 µs — ${PASS_AVG ? 'PASS' : 'FAIL'})`);
console.log(`- Full scan (sum-of-avgs) latency: **${aggMs.toFixed(3)} ms** (target: <10 ms — ${aggMs < 10 ? 'PASS' : 'FAIL'})`);
console.log('');
console.log('## Notes');
console.log('');
console.log('- This bench measures the **anomaly-detection arithmetic core**');
console.log('  shared between the JS skill and the upstream `npx neural-trader`');
console.log('  binary. It does NOT cover network fetch latency (~200 ms tail');
console.log('  per cloud roundtrip), which dominates real-world `--signal scan`');
console.log('  and is amortized across all symbols in one batch.');
console.log('- Synthetic OHLCV is mulberry32-seeded, so results are stable');
console.log('  across runs and CI workers.');
console.log('');
console.log('## Refs');
console.log('');
console.log('- ADR-126 §SOTA delta — bench-driven perf work');
console.log('- `plugins/ruflo-neural-trader/skills/trader-signal/SKILL.md` — production scan path');

/**
 * Pipeline message schemas — ADR-126 Phase 5
 *
 * The four neural-trader agents (`market-analyst`, `trading-strategist`,
 * `risk-analyst`, `backtest-engineer`) coordinate as a typed SendMessage
 * pipeline, NOT as parallel role descriptions:
 *
 *   market-analyst       — (RegimeVerdict)   ─→ trading-strategist
 *   trading-strategist   — (SignalProposal[]) ─→ risk-analyst   ◄── BLOCKING
 *   risk-analyst         — (RiskDecision)    ─→ trading-strategist
 *                                              └─→ execute-or-halt
 *
 * `trading-strategist` MUST NOT call the live broker (`--broker <name>`)
 * without a `RiskDecision` with `decision: 'approved'` from `risk-analyst`
 * in the current SendMessage trace. This is the structural risk-gate per
 * ADR-126 — see `trading-strategist.md` for the in-agent enforcement.
 *
 * `backtest-engineer` is an orthogonal lane — it produces signed-artifact
 * promotion candidates (ADR-126 Phase 4) and does NOT participate in the
 * live execution pipeline. It runs in parallel during research, but the
 * hot path of live trading never depends on it.
 *
 * These types are documentation + a future programmatic dispatcher
 * contract. SendMessage payloads today are JSON literals; tomorrow a
 * typed dispatcher can import + validate against this schema.
 *
 * Refs:
 *   - ADR-126 Phase 5      — SendMessage pipeline plan
 *   - CLAUDE.md            — SendMessage protocol + named-agent rules
 *   - SKILL.md files for each agent — the actual call sites
 */

/* ---------------------------------------------------------------------- */
/* market-analyst → trading-strategist                                    */
/* ---------------------------------------------------------------------- */

/**
 * Regime verdict — produced by `market-analyst`, consumed by
 * `trading-strategist`. Identifies the current market regime so the
 * strategist can pick an appropriate strategy family before generating
 * signals.
 */
export interface RegimeVerdict {
  /** Message schema discriminator. */
  type: 'regime-verdict/v1';
  /** Originating agent name (must be `market-analyst` for valid messages). */
  from: 'market-analyst';
  /** ISO timestamp when the verdict was produced. */
  timestamp: string;
  /** The classified regime — one of the six market-analyst categories. */
  regime:
    | 'bull-trending'
    | 'bear-trending'
    | 'ranging'
    | 'high-volatility'
    | 'low-volatility'
    | 'transitioning';
  /** The ticker(s) the verdict applies to. */
  symbols: string[];
  /** Confidence score in [0,1]. */
  confidence: number;
  /** Optional supporting indicators (ADX, RSI, MACD, VIX, ...). */
  indicators?: Record<string, number>;
}

/* ---------------------------------------------------------------------- */
/* trading-strategist → risk-analyst                                      */
/* ---------------------------------------------------------------------- */

/**
 * Signal proposal — produced by `trading-strategist`, consumed by
 * `risk-analyst`. Represents a proposed live-trade action that requires
 * risk approval before execution.
 */
export interface SignalProposal {
  /** Message schema discriminator. */
  type: 'signal-proposal/v1';
  /** Originating agent name. */
  from: 'trading-strategist';
  /** Unique signal id — used to correlate the RiskDecision response. */
  signalId: string;
  /** ISO timestamp when the proposal was created. */
  timestamp: string;
  /** Symbol to trade. */
  symbol: string;
  /** Direction. */
  side: 'long' | 'short' | 'close';
  /** Strategy that produced the proposal. */
  strategyId: string;
  /** Position size as % of portfolio (e.g. 0.02 = 2%). */
  sizePct: number;
  /** Z-score / confidence score driving the entry. */
  confidence: number;
  /** Reference to the upstream regime that motivated the trade. */
  regime?: RegimeVerdict['regime'];
  /** Optional metadata — model attribution, indicator snapshot, etc. */
  metadata?: Record<string, unknown>;
}

/* ---------------------------------------------------------------------- */
/* risk-analyst → trading-strategist                                      */
/* ---------------------------------------------------------------------- */

/**
 * Risk decision — produced by `risk-analyst`, consumed by
 * `trading-strategist`. The BLOCKING GATE: `trading-strategist` MUST NOT
 * execute a live broker call without a corresponding `RiskDecision` with
 * `decision: 'approved'` for the proposal's `signalId`.
 *
 * Rejection reasons map to the risk-analyst's circuit-breaker / sizing
 * checks (VaR, CVaR, concentration, correlation, drawdown).
 */
export interface RiskDecision {
  /** Message schema discriminator. */
  type: 'risk-decision/v1';
  /** Originating agent name. */
  from: 'risk-analyst';
  /** The signal id this decision responds to (correlates with SignalProposal.signalId). */
  signalId: string;
  /** ISO timestamp when the decision was made. */
  timestamp: string;
  /** Decision — approved means the strategist may call the broker. */
  decision: 'approved' | 'rejected';
  /** Optional size adjustment — risk-analyst may shrink the proposal. */
  adjustedSizePct?: number;
  /** Human-readable reasons (empty array on approval). */
  reasons: string[];
  /** Risk metrics computed for the decision (VaR/CVaR snapshots, etc.). */
  metrics?: {
    var95?: number;
    cvar95?: number;
    portfolioCorrelation?: number;
    concentrationPct?: number;
    drawdownPct?: number;
  };
}

/* ---------------------------------------------------------------------- */
/* Union for typed dispatchers                                            */
/* ---------------------------------------------------------------------- */

/**
 * Discriminated union of every valid SendMessage payload in the
 * neural-trader pipeline. A future programmatic dispatcher can switch
 * on `type` to validate + route incoming messages.
 */
export type PipelineMessage = RegimeVerdict | SignalProposal | RiskDecision;

// SignedBacktestArtifact — runtime ES module mirror of signed-artifact.ts.
//
// Why this file exists:
//   The plugin (ruflo-neural-trader) has no package.json / tsconfig /
//   build step — it ships skills + agents + scripts only. The `.ts`
//   file is the documented type-shape + source of truth (ADR-126
//   Phase 4 spec). This `.mjs` file is the runtime that the smoke
//   (`scripts/smoke-neural-trader-backtest-signing.mjs`) imports
//   directly, with zero compile step.
//
// Both files MUST stay in sync — any change to one is a change to the
// other. The smoke contract-checks the .ts file and runtime-tests the
// .mjs file; a divergence will fail one half of the smoke.
//
// Refs: ADR-126 Phase 4, CWE-347 pattern (#1922), ADR-103 witness.

/**
 * Sign the body of a backtest artifact. Returns the fully-formed
 * SignedBacktestArtifact envelope including witnessPublicKey + witnessSignature.
 */
export async function signBacktestArtifact(body, privateKeyHex) {
  const ed = await import('@noble/ed25519');
  const privateKey = hexToBytes(privateKeyHex);
  if (privateKey.length !== 32) {
    throw new Error(
      `signBacktestArtifact: privateKey must be 32 bytes (got ${privateKey.length})`,
    );
  }
  const canonical = canonicalBytes(body);
  const signatureBytes = await ed.signAsync(canonical, privateKey);
  const publicKeyBytes = await ed.getPublicKeyAsync(privateKey);
  return {
    schema: 'ruflo-neural-trader-backtest/v1',
    ...body,
    witnessPublicKey: `ed25519:${bytesToHex(publicKeyBytes)}`,
    witnessSignature: bytesToHex(signatureBytes),
  };
}

/**
 * Verify a signed backtest artifact against a caller-supplied trusted key.
 *
 * Pins to `trustedPublicKey`, NOT to artifact.witnessPublicKey. The latter
 * is attacker-controllable; pinning to it defeats the entire verification.
 * (CWE-347 / #1922 — same pattern the plugin-registry verifier uses.)
 */
export async function verifyBacktestArtifact(artifact, trustedPublicKey) {
  if (!artifact || !artifact.witnessSignature || !trustedPublicKey) return false;
  const ed = await import('@noble/ed25519');
  const body = {
    strategyId: artifact.strategyId,
    paramsHash: artifact.paramsHash,
    dataRange: artifact.dataRange,
    metrics: artifact.metrics,
    runsHash: artifact.runsHash,
    generatedAt: artifact.generatedAt,
  };
  const canonical = canonicalBytes(body);
  try {
    const pubKeyHex = trustedPublicKey.replace(/^ed25519:/, '');
    const pubKey = hexToBytes(pubKeyHex);
    if (pubKey.length !== 32) return false;
    const sig = hexToBytes(artifact.witnessSignature);
    if (sig.length !== 64) return false;
    return await ed.verifyAsync(sig, canonical, pubKey);
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// helpers (parity with .ts source)
// ---------------------------------------------------------------------------

function canonicalBytes(body) {
  const message = JSON.stringify(body);
  return new TextEncoder().encode(message);
}

function hexToBytes(hex) {
  const clean = hex.replace(/^0x/, '');
  if (clean.length % 2 !== 0) {
    throw new Error('hexToBytes: odd-length hex string');
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToHex(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) {
    s += bytes[i].toString(16).padStart(2, '0');
  }
  return s;
}

/**
 * SignedBacktestArtifact — Phase 4 of ADR-126
 *
 * Ed25519-signed envelope for `trading-backtests` entries. The paper→live
 * promotion gate stores backtest results as the artifact below; the cloud
 * backtest pipeline (`trader-cloud-backtest`) verifies the signature with a
 * pinned trusted key BEFORE promoting any artifact to a live strategy.
 *
 * Signing scheme — mirrors the CWE-347 plugin-registry pattern exactly
 * (scripts/smoke-plugin-registry-signature.mjs:80-130, the verified-good
 * reference for "sign with Ed25519, pin to a trusted key, fail closed"):
 *
 *   1. Build the artifact body WITHOUT signature fields
 *      (no `witnessSignature`, no `witnessPublicKey`).
 *   2. `JSON.stringify(...)` plain — no whitespace, no sort.
 *   3. Sign the resulting bytes with Ed25519.
 *   4. Verify pins to a caller-supplied `trustedPublicKey`,
 *      NOT to the self-asserted `witnessPublicKey` field on the artifact
 *      (an attacker controls that field; pinning to it is a no-op).
 *
 * Key sourcing:
 *   - The signer accepts a 32-byte private key as a hex string. The
 *     `trader-backtest` skill resolves the key at runtime via the env var
 *     `RUFLO_WITNESS_KEY_PATH` (a JSON file with a `{ "privateKey": "<hex>" }`
 *     field). If unset, callers may fall back to the legacy ADR-103 witness
 *     key path; if neither is available, the skill stores the artifact in
 *     UNSIGNED degraded mode with a loud warning — never silently.
 *
 *   - The verifier accepts a `trustedPublicKey` as `"ed25519:<hex>"` or
 *     plain `<hex>`. Production deployments pin this in project config.
 *
 * Refs:
 *   - ADR-126 Phase 4   — the integration plan
 *   - ADR-103           — witness temporal history
 *   - CWE-347 / #1922   — the pattern this signing scheme matches
 *   - scripts/smoke-plugin-registry-signature.mjs — the reference smoke
 */

/* ---------------------------------------------------------------------- */
/* Public types                                                           */
/* ---------------------------------------------------------------------- */

export interface SignedBacktestArtifact {
  schema: 'ruflo-neural-trader-backtest/v1';
  strategyId: string;
  paramsHash: string;           // sha256 of canonical params JSON
  dataRange: { from: string; to: string };
  metrics: Record<string, number>;
  runsHash: string;             // sha256 of the canonical runs array JSON
  generatedAt: string;          // ISO timestamp
  witnessPublicKey: string;     // 'ed25519:<hex>' — self-asserted (NOT pinned by verifier)
  witnessSignature: string;     // hex of the Ed25519 signature over the canonical body
}

/** The body that gets signed — everything except the two signature fields. */
export type SignedBacktestArtifactBody = Omit<
  SignedBacktestArtifact,
  'witnessPublicKey' | 'witnessSignature' | 'schema'
>;

/* ---------------------------------------------------------------------- */
/* Signing + verification                                                 */
/* ---------------------------------------------------------------------- */

/**
 * Sign the body of a backtest artifact and return the fully-formed
 * `SignedBacktestArtifact` envelope.
 *
 * The signature covers the artifact body WITHOUT `witnessSignature` and
 * WITHOUT `witnessPublicKey` (CWE-347 pattern). This means an attacker who
 * swaps the served `witnessPublicKey` field cannot bypass verification when
 * the verifier pins to a trusted key (which is the only safe verifier).
 *
 * @param body                 — the artifact body (everything except signature fields + schema)
 * @param privateKeyHex        — 32-byte Ed25519 private key as hex string (no 'ed25519:' prefix)
 * @returns                      — the signed artifact ready to be stored
 */
export async function signBacktestArtifact(
  body: SignedBacktestArtifactBody,
  privateKeyHex: string,
): Promise<SignedBacktestArtifact> {
  const ed = await import('@noble/ed25519');
  const privateKey = hexToBytes(privateKeyHex);
  if (privateKey.length !== 32) {
    throw new Error(
      `signBacktestArtifact: privateKey must be 32 bytes (got ${privateKey.length})`,
    );
  }

  // Canonical body = the artifact WITHOUT signature fields, plain JSON.stringify.
  // Matches scripts/smoke-plugin-registry-signature.mjs:193-200.
  const canonical = canonicalBytes(body);
  const signatureBytes = await ed.signAsync(canonical, privateKey);
  const publicKeyBytes = await ed.getPublicKeyAsync(privateKey);

  return {
    schema: 'ruflo-neural-trader-backtest/v1',
    ...body,
    witnessPublicKey: `ed25519:${bytesToHex(publicKeyBytes)}`,
    witnessSignature: bytesToHex(signatureBytes),
  };
}

/**
 * Verify a signed backtest artifact against a caller-supplied trusted
 * public key. Returns `true` iff the signature is valid for the canonical
 * body under the TRUSTED key.
 *
 * IMPORTANT — the verifier pins to `trustedPublicKey`, NOT to the artifact's
 * `witnessPublicKey` field. The artifact's self-asserted public key is
 * untrusted input: an attacker who tampers with the stored entry can swap
 * that field freely. Pinning to a trusted key supplied by project config
 * is the only safe pattern (CWE-347 / #1922).
 *
 * @param artifact          — the artifact to verify (may have been tampered)
 * @param trustedPublicKey  — caller-supplied trusted pubkey, with or without 'ed25519:' prefix
 * @returns                   — true iff signature verifies against the trusted key
 */
export async function verifyBacktestArtifact(
  artifact: SignedBacktestArtifact,
  trustedPublicKey: string,
): Promise<boolean> {
  if (!artifact || !artifact.witnessSignature || !trustedPublicKey) return false;
  const ed = await import('@noble/ed25519');

  // Strip BOTH signature fields (and schema, which is constant) to get the
  // canonical body that was signed.
  const body: SignedBacktestArtifactBody = {
    strategyId: artifact.strategyId,
    paramsHash: artifact.paramsHash,
    dataRange: artifact.dataRange,
    metrics: artifact.metrics,
    runsHash: artifact.runsHash,
    generatedAt: artifact.generatedAt,
  };
  const canonical = canonicalBytes(body);

  try {
    const pubKeyHex = trustedPublicKey.replace(/^ed25519:/, '');
    const pubKey = hexToBytes(pubKeyHex);
    if (pubKey.length !== 32) return false;
    const sig = hexToBytes(artifact.witnessSignature);
    if (sig.length !== 64) return false;
    return await ed.verifyAsync(sig, canonical, pubKey);
  } catch {
    return false;
  }
}

/* ---------------------------------------------------------------------- */
/* Helpers                                                                */
/* ---------------------------------------------------------------------- */

/**
 * Canonical bytes for signing = `JSON.stringify(body)` UTF-8 encoded.
 *
 * Matches the plugin-registry signer (publish-registry.ts:127-151) and the
 * CWE-347 smoke (smoke-plugin-registry-signature.mjs:193-200): plain
 * `JSON.stringify` with NO whitespace and NO key sort. The body shape is
 * authored by us (the signer), so deterministic key order is guaranteed by
 * construction — no canonicalizer needed.
 */
function canonicalBytes(body: SignedBacktestArtifactBody): Uint8Array {
  const message = JSON.stringify(body);
  return new TextEncoder().encode(message);
}

function hexToBytes(hex: string): Uint8Array {
  const clean = hex.replace(/^0x/, '');
  if (clean.length % 2 !== 0) {
    throw new Error(`hexToBytes: odd-length hex string`);
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToHex(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i++) {
    s += bytes[i].toString(16).padStart(2, '0');
  }
  return s;
}

// SignedAttributionArtifact — runtime ES module mirror of signed-attribution.ts.
//
// Why this file exists:
//   The plugin (ruflo-neural-trader) has no package.json / tsconfig /
//   build step — it ships skills + agents + scripts only. The `.ts`
//   file is the documented type-shape + source of truth (ADR-126
//   Phase 6 spec). This `.mjs` file is the runtime that the smoke
//   (`scripts/smoke-neural-trader-feature-attribution.mjs`) imports
//   directly, with zero compile step.
//
// Both files MUST stay in sync — any change to one is a change to the
// other. The smoke contract-checks the .ts file and runtime-tests the
// .mjs file; a divergence will fail one half of the smoke.
//
// Refs: ADR-126 Phase 6, CWE-347 pattern (#1922), ADR-103 witness.

/* ---------------------------------------------------------------------- */
/* Signing + verification (Ed25519, same scheme as Phase 4)               */
/* ---------------------------------------------------------------------- */

export async function signAttributionArtifact(body, privateKeyHex) {
  const ed = await import('@noble/ed25519');
  const privateKey = hexToBytes(privateKeyHex);
  if (privateKey.length !== 32) {
    throw new Error(
      `signAttributionArtifact: privateKey must be 32 bytes (got ${privateKey.length})`,
    );
  }
  const canonical = canonicalBytes(body);
  const signatureBytes = await ed.signAsync(canonical, privateKey);
  const publicKeyBytes = await ed.getPublicKeyAsync(privateKey);
  return {
    schema: 'ruflo-neural-trader-attribution/v1',
    ...body,
    witnessPublicKey: `ed25519:${bytesToHex(publicKeyBytes)}`,
    witnessSignature: bytesToHex(signatureBytes),
  };
}

export async function verifyAttributionArtifact(artifact, trustedPublicKey) {
  if (!artifact || !artifact.witnessSignature || !trustedPublicKey) return false;
  const ed = await import('@noble/ed25519');
  const body = {
    signalId: artifact.signalId,
    modelId: artifact.modelId,
    features: artifact.features,
    graphMetadata: artifact.graphMetadata,
    generatedAt: artifact.generatedAt,
  };
  const canonical = canonicalBytes(body);
  try {
    const pubKeyHex = trustedPublicKey.replace(/^ed25519:/, '');
    const pubKey = hexToBytes(pubKeyHex);
    if (pubKey.length !== 32) return false;
    const sig = hexToBytes(artifact.witnessSignature);
    if (sig.length !== 64) return false;
    return await ed.verifyAsync(sig, canonical, pubKey);
  } catch {
    return false;
  }
}

/* ---------------------------------------------------------------------- */
/* Single-entry PageRank (forward-push) — local power-iteration fallback  */
/* ---------------------------------------------------------------------- */

export function localSingleEntryPageRank(graph, opts) {
  const n = graph.nodes.length;
  if (n === 0) return { scores: [], iterations: 0 };
  const damping = opts.damping ?? 0.85;
  const maxIter = opts.maxIterations ?? 100;
  const tol = opts.tolerance ?? 1e-8;
  const src = opts.sourceIndex;
  if (src < 0 || src >= n) {
    throw new Error(
      `localSingleEntryPageRank: sourceIndex ${src} out of range [0, ${n})`,
    );
  }

  const personalization = new Float64Array(n);
  personalization[src] = 1;

  const rng = mulberry32(opts.seed);
  let r = new Float64Array(n);
  let sum = 0;
  for (let i = 0; i < n; i++) {
    r[i] = 1e-6 + rng();
    sum += r[i];
  }
  for (let i = 0; i < n; i++) r[i] /= sum;

  let iterations = 0;
  for (let step = 0; step < maxIter; step++) {
    iterations++;
    const next = new Float64Array(n);
    for (let i = 0; i < n; i++) {
      const out = graph.edges[i];
      if (!out || out.length === 0) {
        next[src] += damping * r[i];
        continue;
      }
      let totalW = 0;
      for (let k = 0; k < out.length; k++) totalW += Math.max(0, out[k].weight);
      if (totalW === 0) {
        next[src] += damping * r[i];
        continue;
      }
      for (let k = 0; k < out.length; k++) {
        const w = Math.max(0, out[k].weight);
        next[out[k].target] += (damping * r[i] * w) / totalW;
      }
    }
    for (let i = 0; i < n; i++) next[i] += (1 - damping) * personalization[i];

    let delta = 0;
    for (let i = 0; i < n; i++) delta += Math.abs(next[i] - r[i]);
    r = next;
    if (delta < tol) break;
  }

  let s = 0;
  for (let i = 0; i < n; i++) s += r[i];
  if (s > 0) for (let i = 0; i < n; i++) r[i] /= s;

  return { scores: Array.from(r), iterations };
}

/* ---------------------------------------------------------------------- */
/* MCP dispatch                                                            */
/* ---------------------------------------------------------------------- */

export function isPageRankMcpAvailable() {
  try {
    const tool = globalThis['mcp__ruflo-sublinear__page-rank-entry'];
    return typeof tool === 'function';
  } catch {
    return false;
  }
}

export async function singleEntryPageRank(graph, opts) {
  if (isPageRankMcpAvailable()) {
    try {
      const tool = globalThis['mcp__ruflo-sublinear__page-rank-entry'];
      const out = await tool({
        nodes: graph.nodes,
        edges: graph.edges,
        sourceIndex: opts.sourceIndex,
        damping: opts.damping ?? 0.85,
        maxIterations: opts.maxIterations ?? 100,
        tolerance: opts.tolerance ?? 1e-8,
        seed: opts.seed,
      });
      if (out && Array.isArray(out.scores)) {
        return {
          scores: out.scores,
          iterations: out.iterations ?? 0,
          path: 'mcp',
        };
      }
    } catch {
      // fall through to local
    }
  }
  return { ...localSingleEntryPageRank(graph, opts), path: 'local' };
}

/* ---------------------------------------------------------------------- */
/* Ranking helper                                                          */
/* ---------------------------------------------------------------------- */

export function topKFeatures(graph, scores, k, excludeIndex) {
  const items = [];
  for (let i = 0; i < graph.nodes.length; i++) {
    if (i === excludeIndex) continue;
    items.push({ name: graph.nodes[i], score: scores[i] ?? 0, idx: i });
  }
  items.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return a.idx - b.idx;
  });
  return items.slice(0, k).map((item, i) => ({
    name: item.name,
    score: item.score,
    rank: i + 1,
  }));
}

/* ---------------------------------------------------------------------- */
/* Helpers                                                                */
/* ---------------------------------------------------------------------- */

function canonicalBytes(body) {
  const message = JSON.stringify(body);
  return new TextEncoder().encode(message);
}

function hexToBytes(hex) {
  const clean = hex.replace(/^0x/, '');
  if (clean.length % 2 !== 0) {
    throw new Error('hexToBytes: odd-length hex string');
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToHex(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) {
    s += bytes[i].toString(16).padStart(2, '0');
  }
  return s;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * SignedAttributionArtifact — Phase 6 of ADR-126
 *
 * Ed25519-signed envelope for feature-attribution rankings. Given a trading
 * signal (LSTM / Transformer / N-BEATS prediction), the `trader-explain`
 * skill builds a feature-contribution graph, runs single-entry PageRank
 * (forward-push from the signal output node), and stores the top-K ranked
 * features to `trading-analysis` as the artifact below. The signature gives
 * the result regulator-grade tamper evidence (EU AI Act interpretability,
 * SEC Reg-AI explainability) and the seed field makes the ranking
 * reproducible across two identical runs.
 *
 * Signing scheme — identical to Phase 4's `SignedBacktestArtifact` (the
 * CWE-347 plugin-registry pattern, #1922):
 *
 *   1. Build the artifact body WITHOUT signature fields
 *      (no `witnessSignature`, no `witnessPublicKey`, no `schema`).
 *   2. `JSON.stringify(...)` plain — no whitespace, no sort.
 *   3. Sign the resulting bytes with Ed25519.
 *   4. Verify pins to a caller-supplied `trustedPublicKey`,
 *      NOT to the self-asserted `witnessPublicKey` field on the artifact
 *      (an attacker controls that field; pinning to it is a no-op).
 *
 * This module deliberately re-uses the same canonical-bytes layout and
 * helper functions as `signed-artifact.ts`. The shape only differs in the
 * envelope's payload fields (`features` + `graphMetadata` + `signalId` +
 * `modelId` instead of backtest metrics + runsHash).
 *
 * Refs:
 *   - ADR-126 Phase 6   — the integration plan (feature attribution)
 *   - ADR-126 Phase 4   — the sibling signing scheme we reuse
 *   - ADR-123           — single-entry PageRank substrate
 *   - ADR-103           — witness temporal history
 *   - CWE-347 / #1922   — the pattern this signing scheme matches
 */

/* ---------------------------------------------------------------------- */
/* Public types                                                           */
/* ---------------------------------------------------------------------- */

/** One ranked feature contribution to the model's output. */
export interface AttributionFeature {
  /** Stable feature identifier. e.g. `rsi_14`, `attention_head_3`, `price_close_t-7`. */
  name: string;
  /** PageRank score in [0, 1] (mass-normalized over all features). */
  score: number;
  /** 1-indexed rank in the descending-score ordering. */
  rank: number;
}

export interface SignedAttributionArtifact {
  schema: 'ruflo-neural-trader-attribution/v1';
  /** The signal whose prediction is being explained. */
  signalId: string;
  /** Which model produced the signal. e.g. `lstm-v3`, `transformer-attn8h-v2`. */
  modelId: string;
  /** Top-K ranked features (rank 1 = most influential). */
  features: AttributionFeature[];
  /** Reproducibility metadata — same seed + same graph → same ranking. */
  graphMetadata: {
    nodeCount: number;
    edgeCount: number;
    pageRankIterations: number;
    /** Seed fed to the PageRank initializer. Required for reproducibility. */
    seed: number;
  };
  generatedAt: string;
  witnessPublicKey: string;
  witnessSignature: string;
}

/** Body that gets signed — everything except the two signature fields + schema. */
export type SignedAttributionArtifactBody = Omit<
  SignedAttributionArtifact,
  'witnessPublicKey' | 'witnessSignature' | 'schema'
>;

/* ---------------------------------------------------------------------- */
/* Signing + verification                                                 */
/* ---------------------------------------------------------------------- */

/**
 * Sign the body of an attribution artifact and return the fully-formed
 * `SignedAttributionArtifact` envelope.
 *
 * The signature covers the artifact body WITHOUT `witnessSignature` and
 * WITHOUT `witnessPublicKey` (CWE-347 pattern, same as Phase 4). The
 * verifier MUST pin to a trusted key for the pin to be a real defense.
 *
 * @param body                — artifact body (everything except signature fields + schema)
 * @param privateKeyHex       — 32-byte Ed25519 private key as hex (no 'ed25519:' prefix)
 * @returns                     the signed artifact ready to be stored
 */
export async function signAttributionArtifact(
  body: SignedAttributionArtifactBody,
  privateKeyHex: string,
): Promise<SignedAttributionArtifact> {
  const ed = await import('@noble/ed25519');
  const privateKey = hexToBytes(privateKeyHex);
  if (privateKey.length !== 32) {
    throw new Error(
      `signAttributionArtifact: privateKey must be 32 bytes (got ${privateKey.length})`,
    );
  }

  const canonical = canonicalBytes(body);
  const signatureBytes = await ed.signAsync(canonical, privateKey);
  const publicKeyBytes = await ed.getPublicKeyAsync(privateKey);

  return {
    schema: 'ruflo-neural-trader-attribution/v1',
    ...body,
    witnessPublicKey: `ed25519:${bytesToHex(publicKeyBytes)}`,
    witnessSignature: bytesToHex(signatureBytes),
  };
}

/**
 * Verify a signed attribution artifact against a caller-supplied trusted
 * public key. Returns `true` iff the signature is valid for the canonical
 * body under the TRUSTED key.
 *
 * IMPORTANT — pins to `trustedPublicKey`, NOT to `artifact.witnessPublicKey`
 * (CWE-347 / #1922). The artifact's self-asserted public key is untrusted
 * input that an attacker can swap.
 *
 * @param artifact          — the artifact to verify (may have been tampered)
 * @param trustedPublicKey  — caller-supplied trusted pubkey, with or without 'ed25519:' prefix
 */
export async function verifyAttributionArtifact(
  artifact: SignedAttributionArtifact,
  trustedPublicKey: string,
): Promise<boolean> {
  if (!artifact || !artifact.witnessSignature || !trustedPublicKey) return false;
  const ed = await import('@noble/ed25519');

  const body: SignedAttributionArtifactBody = {
    signalId: artifact.signalId,
    modelId: artifact.modelId,
    features: artifact.features,
    graphMetadata: artifact.graphMetadata,
    generatedAt: artifact.generatedAt,
  };
  const canonical = canonicalBytes(body);

  try {
    const pubKeyHex = trustedPublicKey.replace(/^ed25519:/, '');
    const pubKey = hexToBytes(pubKeyHex);
    if (pubKey.length !== 32) return false;
    const sig = hexToBytes(artifact.witnessSignature);
    if (sig.length !== 64) return false;
    return await ed.verifyAsync(sig, canonical, pubKey);
  } catch {
    return false;
  }
}

/* ---------------------------------------------------------------------- */
/* Single-entry PageRank (forward-push)                                   */
/* ---------------------------------------------------------------------- */

/** Sparse directed graph used by the local PageRank fallback. */
export interface AttributionGraph {
  /** Stable node identifiers — `nodes[i]` is feature-id of node index `i`. */
  nodes: string[];
  /**
   * Adjacency list: `edges[i]` = array of `{ target, weight }` pairs giving
   * the outgoing edges from node `i`. `target` is a node index.
   */
  edges: Array<Array<{ target: number; weight: number }>>;
}

export interface PageRankOptions {
  /** Index of the source node (the signal output node). */
  sourceIndex: number;
  /** Damping factor (typically 0.85). */
  damping?: number;
  /** Max power-iteration steps. */
  maxIterations?: number;
  /** L1 convergence threshold. */
  tolerance?: number;
  /**
   * RNG seed for the initializer. With damping=0 (or no edges) this is
   * the only source of variation between runs — used to assert
   * reproducibility in the Phase 6 smoke.
   */
  seed: number;
}

export interface PageRankResult {
  /** PageRank scores aligned with `graph.nodes` (sum ≈ 1). */
  scores: number[];
  /** Number of power-iteration steps actually executed. */
  iterations: number;
}

/**
 * Local JS power-iteration single-entry PageRank — the fallback used when
 * `mcp__ruflo-sublinear__page-rank-entry` is not registered in the runtime.
 *
 * The math: standard personalized PageRank with the personalization vector
 * concentrated entirely on the source node. Forward-push semantics in the
 * limit, plain power iteration on a small in-memory graph in practice.
 * Seeded so that two runs with the same graph + same seed return byte-
 * identical ordering (asserted by the Phase 6 smoke's reproducibility
 * check).
 */
export function localSingleEntryPageRank(
  graph: AttributionGraph,
  opts: PageRankOptions,
): PageRankResult {
  const n = graph.nodes.length;
  if (n === 0) return { scores: [], iterations: 0 };
  const damping = opts.damping ?? 0.85;
  const maxIter = opts.maxIterations ?? 100;
  const tol = opts.tolerance ?? 1e-8;
  const src = opts.sourceIndex;
  if (src < 0 || src >= n) {
    throw new Error(
      `localSingleEntryPageRank: sourceIndex ${src} out of range [0, ${n})`,
    );
  }

  // Personalization vector concentrated on src.
  const personalization = new Float64Array(n);
  personalization[src] = 1;

  // Initialize: seeded deterministic noise then re-normalize so the start
  // vector still sums to 1. The seed controls the initialization only —
  // PageRank converges to the same stationary distribution regardless, but
  // the iteration *order* and the path through the state space depend on
  // the seed when ties are present. This is what the smoke asserts.
  let rng = mulberry32(opts.seed);
  let r = new Float64Array(n);
  let sum = 0;
  for (let i = 0; i < n; i++) {
    // Small positive noise so we don't divide by zero on degenerate graphs.
    r[i] = 1e-6 + rng();
    sum += r[i];
  }
  for (let i = 0; i < n; i++) r[i] /= sum;

  let iterations = 0;
  for (let step = 0; step < maxIter; step++) {
    iterations++;
    const next = new Float64Array(n);
    // Distribute current mass over outgoing edges, weighted.
    for (let i = 0; i < n; i++) {
      const out = graph.edges[i];
      if (!out || out.length === 0) {
        // Dangling node — distribute its mass back to the personalization.
        next[src] += damping * r[i];
        continue;
      }
      let totalW = 0;
      for (let k = 0; k < out.length; k++) totalW += Math.max(0, out[k].weight);
      if (totalW === 0) {
        next[src] += damping * r[i];
        continue;
      }
      for (let k = 0; k < out.length; k++) {
        const w = Math.max(0, out[k].weight);
        next[out[k].target] += (damping * r[i] * w) / totalW;
      }
    }
    // Add the personalization (teleport) term.
    for (let i = 0; i < n; i++) next[i] += (1 - damping) * personalization[i];

    // L1 convergence
    let delta = 0;
    for (let i = 0; i < n; i++) delta += Math.abs(next[i] - r[i]);
    r = next;
    if (delta < tol) break;
  }

  // Renormalize defensively (drift from floating point + dangling handling).
  let s = 0;
  for (let i = 0; i < n; i++) s += r[i];
  if (s > 0) for (let i = 0; i < n; i++) r[i] /= s;

  return { scores: Array.from(r), iterations };
}

/* ---------------------------------------------------------------------- */
/* MCP dispatch                                                            */
/* ---------------------------------------------------------------------- */

/**
 * True iff `mcp__ruflo-sublinear__page-rank-entry` is registered in the
 * current runtime (the agent sandbox or the host process). Mirrors the
 * `SublinearAdapter.isMcpAvailable()` pattern from Phase 3.
 */
export function isPageRankMcpAvailable(): boolean {
  try {
    const tool = (globalThis as Record<string, unknown>)[
      'mcp__ruflo-sublinear__page-rank-entry'
    ];
    return typeof tool === 'function';
  } catch {
    return false;
  }
}

/**
 * Dispatch to `mcp__ruflo-sublinear__page-rank-entry` when available, fall
 * through to the local power-iteration kernel otherwise. Either way the
 * math is single-entry forward-push PageRank with the personalization
 * vector concentrated on `sourceIndex`.
 */
export async function singleEntryPageRank(
  graph: AttributionGraph,
  opts: PageRankOptions,
): Promise<PageRankResult & { path: 'mcp' | 'local' }> {
  if (isPageRankMcpAvailable()) {
    try {
      const tool = (globalThis as Record<string, unknown>)[
        'mcp__ruflo-sublinear__page-rank-entry'
      ] as (args: unknown) => Promise<{ scores: number[]; iterations?: number }>;
      const out = await tool({
        nodes: graph.nodes,
        edges: graph.edges,
        sourceIndex: opts.sourceIndex,
        damping: opts.damping ?? 0.85,
        maxIterations: opts.maxIterations ?? 100,
        tolerance: opts.tolerance ?? 1e-8,
        seed: opts.seed,
      });
      if (out && Array.isArray(out.scores)) {
        return {
          scores: out.scores,
          iterations: out.iterations ?? 0,
          path: 'mcp',
        };
      }
    } catch {
      // fall through to local
    }
  }
  return { ...localSingleEntryPageRank(graph, opts), path: 'local' };
}

/* ---------------------------------------------------------------------- */
/* Ranking helper                                                          */
/* ---------------------------------------------------------------------- */

/**
 * Convert a `(graph, scores)` pair into a top-K `AttributionFeature[]` ready
 * to drop into `SignedAttributionArtifact.features`. Ties broken
 * deterministically by node index (lower index wins) so the ranking is
 * reproducible.
 */
export function topKFeatures(
  graph: AttributionGraph,
  scores: number[],
  k: number,
  excludeIndex?: number,
): AttributionFeature[] {
  const items: Array<{ name: string; score: number; idx: number }> = [];
  for (let i = 0; i < graph.nodes.length; i++) {
    if (i === excludeIndex) continue;
    items.push({ name: graph.nodes[i], score: scores[i] ?? 0, idx: i });
  }
  items.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return a.idx - b.idx;
  });
  return items.slice(0, k).map((item, i) => ({
    name: item.name,
    score: item.score,
    rank: i + 1,
  }));
}

/* ---------------------------------------------------------------------- */
/* Helpers                                                                */
/* ---------------------------------------------------------------------- */

function canonicalBytes(body: SignedAttributionArtifactBody): Uint8Array {
  const message = JSON.stringify(body);
  return new TextEncoder().encode(message);
}

function hexToBytes(hex: string): Uint8Array {
  const clean = hex.replace(/^0x/, '');
  if (clean.length % 2 !== 0) {
    throw new Error('hexToBytes: odd-length hex string');
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function bytesToHex(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i++) {
    s += bytes[i].toString(16).padStart(2, '0');
  }
  return s;
}

/**
 * Mulberry32 — small, fast, deterministic PRNG. Same algorithm everywhere
 * (no Math.random dependency) so a given seed reproduces byte-for-byte.
 */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// SublinearAdapter — runtime ES module mirror of sublinear-adapter.ts.
//
// Why this file exists:
//   The plugin (ruflo-neural-trader) does not have a `package.json` /
//   tsconfig / build step — it ships skills + agents + scripts only.
//   The `.ts` file in this directory is the documented type-shape and
//   the source of truth for the SublinearAdapter contract (ADR-123
//   §262-289, ADR-126 Phase 3). This `.mjs` file is the runtime that
//   the smoke (`scripts/smoke-neural-trader-portfolio-cg.mjs`) and the
//   bench (`benchmarks/portfolio-cg.bench.ts`) import directly, with
//   zero compile step.
//
// Both files MUST stay in sync — any change to one is a change to the
// other. The smoke includes a contract check that compares the two.
//
// Reference: ADR-126 Phase 3 + ADR-123 Wedge 8.

export class SublinearAdapter {
  /**
   * Two-probe detection (kept in sync with sublinear-adapter.ts):
   *   1) globalThis['mcp__ruflo-sublinear__solve'] is a function
   *   2) process.env.RUFLO_SUBLINEAR_NATIVE === '1' (manual override)
   * Either probe passing triggers the native dispatch; failure of the call
   * itself falls back to the local JS CG kernel.
   */
  static detectSublinearTool() {
    try {
      const tool = globalThis['mcp__ruflo-sublinear__solve'];
      if (typeof tool === 'function') return true;
    } catch {
      /* fall through */
    }
    try {
      const envFlag = typeof process !== 'undefined' && process.env
        ? process.env.RUFLO_SUBLINEAR_NATIVE
        : undefined;
      if (envFlag === '1' || envFlag === 'true') return true;
    } catch {
      /* no process */
    }
    return false;
  }

  /** Back-compat alias for the smoke contract (#2068). */
  static isMcpAvailable() {
    return SublinearAdapter.detectSublinearTool();
  }

  async solveCG(matrix, vector, opts = {}) {
    const start = performance.now();
    const n = matrix.length;
    if (n === 0) return degrade(start, 'empty matrix');
    for (let i = 0; i < n; i++) {
      if (!matrix[i] || matrix[i].length !== n) {
        return degrade(start, `row ${i} is not length ${n} (non-square)`);
      }
    }
    if (vector.length !== n) {
      return degrade(start, `vector length ${vector.length} ≠ matrix size ${n}`);
    }
    if (!isSymmetric(matrix)) {
      return degrade(start, 'matrix not symmetric within 1e-9');
    }

    if (SublinearAdapter.detectSublinearTool()) {
      try {
        const result = await callMcpSolve(matrix, vector, opts);
        return {
          ...result,
          latencyMs: performance.now() - start,
          path: 'cg-mcp',
          method: 'cg-sublinear-native',
          solver: 'sublinear-time-solver@1.7.0',
        };
      } catch {
        // Native dispatch failed (env-var set without harness mount, or
        // tool errored). Fall through to local CG; the artifact records
        // method='cg-local' so the regression is auditable.
      }
    }

    const { solution, iterations, residual } = conjugateGradient(matrix, vector, {
      tolerance: opts.tolerance ?? 1e-6,
      maxIterations: opts.maxIterations ?? 200,
    });
    return {
      solution,
      iterations,
      residual,
      latencyMs: performance.now() - start,
      path: 'cg-local',
      method: 'cg-local',
      solver: 'local-js-cg',
    };
  }
}

function degrade(start, reason) {
  return {
    solution: [],
    iterations: 0,
    residual: Infinity,
    latencyMs: performance.now() - start,
    path: 'cg-local',
    method: 'cg-local',
    solver: 'local-js-cg',
    degraded: true,
    reason,
  };
}

export function conjugateGradient(A, b, opts) {
  const n = b.length;
  const x = new Float64Array(n);
  const r = Float64Array.from(b);
  const p = Float64Array.from(r);
  let rDotR = dot(r, r);
  const tol2 = opts.tolerance * opts.tolerance;
  let iterations = 0;
  for (let k = 0; k < opts.maxIterations; k++) {
    iterations++;
    const Ap = matVec(A, p);
    const pAp = dot(p, Ap);
    if (pAp === 0) break;
    const alpha = rDotR / pAp;
    for (let i = 0; i < n; i++) {
      x[i] += alpha * p[i];
      r[i] -= alpha * Ap[i];
    }
    const newRDotR = dot(r, r);
    if (newRDotR < tol2) {
      rDotR = newRDotR;
      break;
    }
    const beta = newRDotR / rDotR;
    for (let i = 0; i < n; i++) p[i] = r[i] + beta * p[i];
    rDotR = newRDotR;
  }
  return { solution: Array.from(x), iterations, residual: Math.sqrt(rDotR) };
}

/**
 * Neumann/Jacobi series solver — baseline used by the bench to demonstrate
 * the ~40-60× CG speedup. Iterates x_{k+1} = D⁻¹(b − (A − D)·x_k).
 * Converges for diagonally-dominant or SPD inputs with bounded spectral
 * radius of (I − D⁻¹A). Slower than CG by 40-60× at n=256 (Wedge 8).
 */
export function neumannSeries(A, b, opts) {
  const n = b.length;
  const tol = opts.tolerance ?? 1e-6;
  const maxIter = opts.maxIterations ?? 1000;
  const diag = new Float64Array(n);
  for (let i = 0; i < n; i++) diag[i] = A[i][i] || 1;
  // Ping-pong buffers: avoid allocating a fresh Float64Array(n) every iter.
  // Before this change a typical 5-iter solve at n=256 allocated 5×2KB of
  // garbage per call — measurable GC pressure under sustained workload.
  // The two-buffer swap keeps the same algorithm (Jacobi-style update from
  // `cur` into `next`, convergence check, swap) with zero per-iter alloc.
  // ADR-126 follow-up #49 — bench-driven perf note.
  let cur = new Float64Array(n);
  let next = new Float64Array(n);
  let iterations = 0;
  for (let k = 0; k < maxIter; k++) {
    iterations++;
    for (let i = 0; i < n; i++) {
      let off = 0;
      const row = A[i];
      for (let j = 0; j < n; j++) {
        if (j !== i) off += row[j] * cur[j];
      }
      next[i] = (b[i] - off) / diag[i];
    }
    // Convergence check on inf-norm of (next - cur).
    let d = 0;
    for (let i = 0; i < n; i++) {
      const e = Math.abs(next[i] - cur[i]);
      if (e > d) d = e;
    }
    // Swap: next becomes the new cur; the old cur is reused as next-scratch.
    const tmp = cur;
    cur = next;
    next = tmp;
    if (d < tol) break;
  }
  // Residual ||A·x − b||₂ where x is the latest cur after the swap.
  const Ax = matVec(A, cur);
  let r2 = 0;
  for (let i = 0; i < n; i++) {
    const d = Ax[i] - b[i];
    r2 += d * d;
  }
  return { solution: Array.from(cur), iterations, residual: Math.sqrt(r2) };
}

function matVec(A, x) {
  const n = A.length;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const row = A[i];
    let s = 0;
    for (let j = 0; j < n; j++) s += row[j] * x[j];
    out[i] = s;
  }
  return out;
}

function dot(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
}

function isSymmetric(A) {
  const n = A.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (Math.abs(A[i][j] - A[j][i]) > 1e-9) return false;
    }
  }
  return true;
}

async function callMcpSolve(matrix, vector, opts) {
  const tool = globalThis['mcp__ruflo-sublinear__solve'];
  if (typeof tool !== 'function') {
    throw new Error('mcp__ruflo-sublinear__solve not available');
  }
  const out = await tool({
    matrix,
    rhs: vector,
    algorithm: 'cg',
    tolerance: opts.tolerance ?? 1e-6,
    maxIterations: opts.maxIterations ?? 200,
  });
  if (!out || !Array.isArray(out.solution)) {
    throw new Error('mcp__ruflo-sublinear__solve returned invalid shape');
  }
  return {
    solution: out.solution,
    iterations: out.iterations ?? 0,
    residual: out.residual ?? 0,
  };
}

export const sublinearAdapter = new SublinearAdapter();

/**
 * SublinearAdapter — Phase 3 of ADR-126
 *
 * Wraps the Wedge-8 path from ADR-123 (`mcp__ruflo-sublinear__solve`,
 * algorithm=CG) for the mean-variance portfolio optimisation problem
 *   Σ · x = μ
 * where Σ is the (assumed) symmetric positive-definite asset-covariance
 * matrix and μ is the expected-return vector.
 *
 * Performance contract (ADR-123 §162, Row 8):
 *   • Neumann series:  ~50 µs   (legacy `npx neural-trader --portfolio optimize`)
 *   • Conjugate Grad:  ~816 ns  (this adapter, n=256)
 *   ⇒ 40-60× measured speedup, parity within 1e-4 on a fixed seed.
 *
 * Why a local CG implementation:
 *   - At ADR-126 Phase 3 write-time, the `ruflo-sublinear` plugin
 *     (ADR-123 Phase 1) has not yet been published on the IPFS registry.
 *     The MCP tool `mcp__ruflo-sublinear__solve` may not be invocable
 *     from inside an agent task (depends on daemon state).
 *   - The point of Phase 3 is the speedup, not the dispatch mechanism.
 *     A self-contained ~50-LOC CG kernel ships now; when the upstream
 *     plugin lands, the `solveCG` body is one MCP call away (the call
 *     site, the input/output shapes, and the smoke contract all stay
 *     identical).
 *
 * Detection:
 *   `SublinearAdapter.detectSublinearTool()` returns true iff the native
 *   `mcp__ruflo-sublinear__solve` dispatch surface is reachable from this
 *   runtime. Two probes are tried, in order:
 *     1) globalThis['mcp__ruflo-sublinear__solve'] is a function — this
 *        is how the ruflo MCP harness mounts tools into the agent runtime.
 *     2) process.env.RUFLO_SUBLINEAR_NATIVE === '1' — manual override for
 *        environments where the tool surface is provided out-of-band
 *        (e.g. a daemon-side spawn or a sidecar tool runner that's
 *        addressed by the same name through a different transport).
 *   When either probe passes, the adapter routes through `callMcpSolve`
 *   and tags the result with `method: 'cg-sublinear-native'` and
 *   `solver: 'sublinear-time-solver@1.7.0'`. Otherwise it falls back to
 *   the embedded CG kernel and tags `method: 'cg-local'`, solver
 *   `'local-js-cg'`. The legacy `isMcpAvailable()` static is preserved
 *   as an alias for back-compat with the smoke contract.
 *
 *   The `path` field is kept (`'cg-local' | 'cg-mcp'`) for wire
 *   compatibility with the Phase 3 baseline; `method` is the human-
 *   readable label downstream callers should record in artifact metadata.
 *
 * SPD validation:
 *   Covariance matrices are SPD by construction (Cov(X,X) is a Gram matrix
 *   on a real inner-product space). We still do a cheap sanity check —
 *   square + symmetric — and emit a `degraded` warning if either fails,
 *   in which case the caller should fall back to the legacy Neumann path.
 *
 * Refs:
 *   - ADR-123 §162 (Wedge 8) — the 40-60× speedup claim and parity bound
 *   - ADR-123 §262-289       — the SublinearAdapter contract shape
 *   - ADR-126 Phase 3        — the integration plan
 *   - upstream `sublinear-time-solver@1.7.0` — the production CG kernel
 */

/* ---------------------------------------------------------------------- */
/* Public types                                                           */
/* ---------------------------------------------------------------------- */

export interface SolveOptions {
  /** Convergence tolerance on the residual L2 norm. Default 1e-6. */
  tolerance?: number;
  /** Maximum CG iterations. Default 200 (more than enough for n≤1024 SPD). */
  maxIterations?: number;
}

export interface SolveResult {
  /** The solution vector x such that A·x ≈ b. */
  solution: number[];
  /** Number of CG iterations executed. */
  iterations: number;
  /** Final residual L2 norm ||A·x − b||₂. */
  residual: number;
  /** Wall-clock latency of the solve in milliseconds. */
  latencyMs: number;
  /**
   * Which dispatch path was used (wire-compatible with Phase 3 baseline).
   *  - `cg-mcp`   — native MCP dispatch (sublinear-time-solver kernel)
   *  - `cg-local` — embedded JS CG fallback
   */
  path: 'cg-local' | 'cg-mcp';
  /**
   * Human-readable method label for artifact provenance metadata. Downstream
   * callers (e.g. trader-portfolio-cg) record this alongside the weights so
   * the auditor can tell at a glance which solver produced the artifact.
   *  - `cg-sublinear-native` — native dispatch via mcp__ruflo-sublinear__solve
   *  - `cg-local`            — embedded JS CG fallback
   */
  method: 'cg-sublinear-native' | 'cg-local';
  /**
   * Identifies the actual kernel that produced the solution. Pinned to the
   * upstream version that the native dispatch targets, or `'local-js-cg'`
   * when the embedded fallback ran.
   */
  solver: 'sublinear-time-solver@1.7.0' | 'local-js-cg';
  /** True if input failed SPD sanity checks; caller should fall back. */
  degraded?: boolean;
  /** Human-readable reason when `degraded` is true. */
  reason?: string;
}

/* ---------------------------------------------------------------------- */
/* SublinearAdapter                                                       */
/* ---------------------------------------------------------------------- */

export class SublinearAdapter {
  /**
   * Detection — is `mcp__ruflo-sublinear__solve` reachable in this runtime?
   *
   * Two probes, in priority order:
   *   1) globalThis['mcp__ruflo-sublinear__solve'] is a function. This is the
   *      convention the ruflo MCP harness uses to mount native tools into the
   *      agent runtime when the daemon is up and the plugin is registered.
   *   2) process.env.RUFLO_SUBLINEAR_NATIVE === '1'. Manual override for
   *      operator-controlled rollouts (canary, A/B) where the harness mount
   *      happens out-of-band — the adapter will attempt `callMcpSolve` and
   *      let that path fail loudly if the tool isn't actually there.
   *
   * The probe is hot-path-safe: no child-process spawn, no filesystem walk,
   * no npm-cache probe. Either the tool surface is mounted or it's not.
   */
  static detectSublinearTool(): boolean {
    try {
      const g = globalThis as unknown as Record<string, unknown>;
      const tool = g['mcp__ruflo-sublinear__solve'];
      if (typeof tool === 'function') return true;
    } catch {
      /* fall through to env probe */
    }
    try {
      // Manual override: operator declares the native surface is reachable.
      const envFlag = typeof process !== 'undefined' && process.env
        ? process.env.RUFLO_SUBLINEAR_NATIVE
        : undefined;
      if (envFlag === '1' || envFlag === 'true') return true;
    } catch {
      /* env unavailable (sandbox without process) — treat as no */
    }
    return false;
  }

  /**
   * Legacy alias preserved for the smoke contract (#2068). New code should
   * call `detectSublinearTool()` for clarity — `isMcpAvailable()` covers only
   * the globalThis probe historically, but is now wired to the same two-probe
   * detection so the env-var override is honoured everywhere.
   */
  static isMcpAvailable(): boolean {
    return SublinearAdapter.detectSublinearTool();
  }

  /**
   * Solve A·x = b via Conjugate Gradient.
   *
   * Contract:
   *   - `matrix` MUST be a square 2-D array (n × n). Matrices that are
   *     not square or whose dimensions disagree with `vector.length` are
   *     rejected with `degraded: true` (the caller should fall back).
   *   - `matrix` SHOULD be symmetric positive-definite. We check the
   *     "symmetric" half cheaply (max |A[i,j] − A[j,i]| ≤ 1e-9). For SPD
   *     we trust the caller — covariance matrices are SPD by construction.
   *   - `vector.length` MUST equal `matrix.length`.
   *
   * On any contract violation the method returns a `degraded: true` result
   * with the partial solution (zero vector) and a `reason` string. The
   * caller (e.g. the `trader-portfolio-cg` skill) then falls back to
   * `npx neural-trader --portfolio optimize` (legacy Neumann) and records
   * `method: 'neumann-fallback'` in the artifact metadata.
   */
  async solveCG(
    matrix: number[][],
    vector: number[],
    opts: SolveOptions = {},
  ): Promise<SolveResult> {
    const start = performance.now();

    // --- Validation ---
    const n = matrix.length;
    if (n === 0) {
      return this.degrade(start, 'empty matrix');
    }
    for (let i = 0; i < n; i++) {
      if (!matrix[i] || matrix[i].length !== n) {
        return this.degrade(start, `row ${i} is not length ${n} (non-square)`);
      }
    }
    if (vector.length !== n) {
      return this.degrade(
        start,
        `vector length ${vector.length} ≠ matrix size ${n}`,
      );
    }
    if (!isSymmetric(matrix)) {
      return this.degrade(start, 'matrix not symmetric within 1e-9');
    }

    // --- Native MCP path (preferred when reachable) ---
    if (SublinearAdapter.detectSublinearTool()) {
      try {
        const result = await callMcpSolve(matrix, vector, opts);
        return {
          ...result,
          latencyMs: performance.now() - start,
          path: 'cg-mcp',
          method: 'cg-sublinear-native',
          solver: 'sublinear-time-solver@1.7.0',
        };
      } catch {
        // Fall through to local kernel on any MCP error — the operator may
        // have set RUFLO_SUBLINEAR_NATIVE=1 in an environment where the tool
        // surface is not actually present. The artifact will record
        // method='cg-local' so the regression is visible in the audit trail.
      }
    }

    // --- Local CG kernel ---
    const { solution, iterations, residual } = conjugateGradient(
      matrix,
      vector,
      {
        tolerance: opts.tolerance ?? 1e-6,
        maxIterations: opts.maxIterations ?? 200,
      },
    );
    return {
      solution,
      iterations,
      residual,
      latencyMs: performance.now() - start,
      path: 'cg-local',
      method: 'cg-local',
      solver: 'local-js-cg',
    };
  }

  private degrade(start: number, reason: string): SolveResult {
    return {
      solution: [],
      iterations: 0,
      residual: Infinity,
      latencyMs: performance.now() - start,
      path: 'cg-local',
      method: 'cg-local',
      solver: 'local-js-cg',
      degraded: true,
      reason,
    };
  }
}

/* ---------------------------------------------------------------------- */
/* Conjugate Gradient kernel — dense form, optimal for n ≤ ~1024          */
/* ---------------------------------------------------------------------- */

/**
 * Solve A·x = b where A is SPD. Returns the solution, iteration count,
 * and final residual norm.
 *
 * Classical CG, no preconditioning. For SPD inputs this converges in at
 * most n iterations (and typically far fewer — clustered eigenvalues).
 * Reference: Shewchuk, "An Introduction to the Conjugate Gradient Method
 * Without the Agonizing Pain", 1994.
 */
export function conjugateGradient(
  A: number[][],
  b: number[],
  opts: { tolerance: number; maxIterations: number },
): { solution: number[]; iterations: number; residual: number } {
  const n = b.length;
  const x = new Float64Array(n);
  // r = b − A·x; with x = 0 initial guess, r = b
  const r = Float64Array.from(b);
  const p = Float64Array.from(r);
  let rDotR = dot(r, r);

  const tol2 = opts.tolerance * opts.tolerance;
  let iterations = 0;
  for (let k = 0; k < opts.maxIterations; k++) {
    iterations++;
    const Ap = matVec(A, p);
    const pAp = dot(p, Ap);
    if (pAp === 0) break;
    const alpha = rDotR / pAp;
    for (let i = 0; i < n; i++) {
      x[i] += alpha * p[i];
      r[i] -= alpha * Ap[i];
    }
    const newRDotR = dot(r, r);
    if (newRDotR < tol2) {
      rDotR = newRDotR;
      break;
    }
    const beta = newRDotR / rDotR;
    for (let i = 0; i < n; i++) p[i] = r[i] + beta * p[i];
    rDotR = newRDotR;
  }
  return {
    solution: Array.from(x),
    iterations,
    residual: Math.sqrt(rDotR),
  };
}

/* ---------------------------------------------------------------------- */
/* Math primitives                                                        */
/* ---------------------------------------------------------------------- */

function matVec(A: number[][], x: Float64Array | number[]): Float64Array {
  const n = A.length;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const row = A[i];
    let s = 0;
    for (let j = 0; j < n; j++) s += row[j] * x[j];
    out[i] = s;
  }
  return out;
}

function dot(a: Float64Array | number[], b: Float64Array | number[]): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
}

function isSymmetric(A: number[][]): boolean {
  const n = A.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (Math.abs(A[i][j] - A[j][i]) > 1e-9) return false;
    }
  }
  return true;
}

/* ---------------------------------------------------------------------- */
/* MCP-tool dispatch (resolved at runtime; signature pinned to ADR-123)   */
/* ---------------------------------------------------------------------- */

interface McpSolveOutput {
  solution: number[];
  iterations: number;
  residual: number;
}

async function callMcpSolve(
  matrix: number[][],
  vector: number[],
  opts: SolveOptions,
): Promise<McpSolveOutput> {
  const g = globalThis as unknown as Record<string, unknown>;
  const tool = g['mcp__ruflo-sublinear__solve'] as
    | ((args: unknown) => Promise<unknown>)
    | undefined;
  if (typeof tool !== 'function') {
    throw new Error('mcp__ruflo-sublinear__solve not available');
  }
  const out = (await tool({
    matrix,
    rhs: vector,
    algorithm: 'cg',
    tolerance: opts.tolerance ?? 1e-6,
    maxIterations: opts.maxIterations ?? 200,
  })) as Partial<McpSolveOutput> | undefined;
  if (!out || !Array.isArray(out.solution)) {
    throw new Error('mcp__ruflo-sublinear__solve returned invalid shape');
  }
  return {
    solution: out.solution,
    iterations: out.iterations ?? 0,
    residual: out.residual ?? 0,
  };
}

